class Solution {
public:
    int maxSumTwoNoOverlap(vector<int>& nums, int firstLen, int secondLen) {
        int n = nums.size();
        auto helper = [&](int l, int m) -> int {
            vector<int> pref(n + 1, 0);
            for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
            int max_l = 0, res = 0;
            for (int i = l + m; i <= n; ++i) {
                max_l = max(max_l, pref[i - m] - pref[i - m - l]);
                res = max(res, max_l + (pref[i] - pref[i - m]));
            }
            return res;
        };
        return max(helper(firstLen, secondLen), helper(secondLen, firstLen));
    }
};

class Solution {
    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        return Math.max(helper(nums, firstLen, secondLen), helper(nums, secondLen, firstLen));
    }

    private int helper(int[] nums, int l, int m) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
        int maxL = 0, res = 0;
        for (int i = l + m; i <= n; ++i) {
            maxL = Math.max(maxL, pref[i - m] - pref[i - m - l]);
            res = Math.max(res, maxL + (pref[i] - pref[i - m]));
        }
        return res;
    }
}

var maxSumTwoNoOverlap = function(nums, firstLen, secondLen) {
    const helper = (l, m) => {
        const n = nums.length;
        const pref = new Array(n + 1).fill(0);
        for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        let maxL = 0;
        let res = 0;
        for (let i = l + m; i <= n; i++) {
            maxL = Math.max(maxL, pref[i - m] - pref[i - m - l]);
            res = Math.max(res, maxL + (pref[i] - pref[i - m]));
        }
        return res;
    };
    return Math.max(helper(firstLen, secondLen), helper(secondLen, firstLen));
};
